 INSERT INTO `single_version` (`version_id`,`target_module`,`project_code`,`version_code`,`version_name`,`route_name`,`status`,`data_status`,`files_json`,`parameters_json`,`provenance_json`,`content_sha256`,`created_by`) SELECT s.`version_id`,s.`target_module`,s.`project_code`,s.`version_code`,s.`version_name`,s.`route_name`,s.`status`,s.`data_status`,s.`files_json`,s.`parameters_json`,s.`provenance_json`,s.`content_sha256`,s.`created_by` FROM `seed_single_version` s WHERE NOT EXISTS(SELECT 1 FROM `single_version` t WHERE (CAST(t.`version_id` AS BINARY) <=> CAST(s.`version_id` AS BINARY)) AND (CAST(t.`target_module` AS BINARY) <=> CAST(s.`target_module` AS BINARY)) AND (CAST(t.`project_code` AS BINARY) <=> CAST(s.`project_code` AS BINARY)) AND (CAST(t.`version_code` AS BINARY) <=> CAST(s.`version_code` AS BINARY)) AND (CAST(t.`version_name` AS BINARY) <=> CAST(s.`version_name` AS BINARY)) AND (CAST(t.`route_name` AS BINARY) <=> CAST(s.`route_name` AS BINARY)) AND (CAST(t.`status` AS BINARY) <=> CAST(s.`status` AS BINARY)) AND (CAST(t.`data_status` AS BINARY) <=> CAST(s.`data_status` AS BINARY)) AND (CAST(t.`files_json` AS BINARY) <=> CAST(s.`files_json` AS BINARY)) AND (CAST(t.`parameters_json` AS BINARY) <=> CAST(s.`parameters_json` AS BINARY)) AND (CAST(t.`provenance_json` AS BINARY) <=> CAST(s.`provenance_json` AS BINARY)) AND (CAST(t.`content_sha256` AS BINARY) <=> CAST(s.`content_sha256` AS BINARY)) AND (CAST(t.`created_by` AS BINARY) <=> CAST(s.`created_by` AS BINARY)));
 INSERT INTO `energy_dept_project` (dept_id,project_code,enabled,create_by,create_time) SELECT target_dept,CONVERT(0x616c676f726974686d5f64656d6f5f3230323631313130 USING utf8mb4),'1','algorithm_demo_init',NOW() WHERE NOT EXISTS(SELECT 1 FROM `energy_dept_project` WHERE dept_id=target_dept AND CAST(project_code AS BINARY)=0x616c676f726974686d5f64656d6f5f3230323631313130);
 INSERT INTO `single_dept_project` (dept_id,project_code,enabled) SELECT target_dept,CONVERT(0x616c676f726974686d5f64656d6f5f3230323631313130 USING utf8mb4),1 WHERE NOT EXISTS(SELECT 1 FROM `single_dept_project` WHERE dept_id=target_dept AND CAST(project_code AS BINARY)=0x616c676f726974686d5f64656d6f5f3230323631313130);
